--Skill Maker (formerly Spell Maker) for Dragons Dogma 2
--Create your own skills as sequences of animations, melee attacks, summons, lightning, explosions and other magical or physical effects
--By alphaZomega
--Requires REFramework
local version = "1.23"

-- GSMAX Headless Runtime: preserve Skill Maker execution semantics, remove editor/UI work.
local GSMAX_HEADLESS_RUNTIME = true

-- v1.3: correlate casts and delayed restores without changing the shell's effects.
local gsmx_diag = { next_id = 0, pending = {}, bad_paths = {} }
local function gsmx_new_id()
    gsmx_diag.next_id = gsmx_diag.next_id + 1
    return gsmx_diag.next_id
end

--=============================================================================
--  ENGINE COMPATIBILITY LAYER - BEGIN
--
--  The current game build ships a new REType layout.  Several engine-facing
--  calls this script relies on do not work against it:
--
--    1. via.Scene.findGameObject(System.String)   throws for every name
--    2. via.Transform.find(System.String)         throws for every name
--    3. sdk.create_managed_array()                returns nil for several app.*
--                                                 element types, and element
--                                                 writes (arr[i] = x) throw
--    4. via.Color.Parse / via.Color .ctor overloads are not always resolvable
--    5. sdk.call_native_func() with arguments may return nil or throw
--       (via.hid.GamePad.getMergedDevice is one of these)
--    6. some managed method lookups return nil, which crashed sdk.hook()
--
--  Everything lives in one table so the main chunk's local budget (Lua's
--  200-local-per-function limit) is untouched.  Every helper tries the stock
--  REFramework path FIRST and only falls back when that call fails, so the
--  script returns to the fast path by itself once REFramework can make these
--  calls again.  No behaviour, data format or UI is changed.
--=============================================================================
local sm32 = { active = {}, notes = {}, hooks_ok = 0, hooks_failed = 0, failed_hooks = {} }

--Record that a fallback path had to be taken (reported once, at load, by sm32.summary)
function sm32.note(key)
	if not sm32.active[key] then
		sm32.active[key] = true
		sm32.notes[#sm32.notes+1] = key
		--after the load summary has been printed, report new fallbacks as they happen (once each)
		if sm32.reported then log.info("[SkillMaker] engine compat: fallback engaged at runtime: "..key) end
	end
end

--A snapshot of one of the per-frame function tables, into a list that is reused instead of built
--again.  A snapshot is taken at all because an entry is allowed to remove itself while the sweep is
--running; making a fresh copy of it every frame, for every live shell and every running node, is a
--steady stream of garbage for no reason.  Each caller has its own list, so one sweep cannot land in
--the middle of another.
sm32.sweeps = {}

function sm32.sweep(tbl, key)
	local list = sm32.sweeps[key]
	if list == nil then list = {}; sm32.sweeps[key] = list end
	local n = 0
	for _, fn in pairs(tbl) do n = n + 1; list[n] = fn end
	for i = n + 1, #list do list[i] = nil end
	return list, n
end

--(1) Find a GameObject by name in a scene
function sm32.find_gameobject(scene, name)
	if scene == nil then return nil end
	local ok, go = pcall(function() return scene:call("findGameObject(System.String)", name) end)
	if ok and go ~= nil then return go end
	sm32.note("Scene.findGameObject")
	local ok2, comps = pcall(function() return scene:call("findComponents(System.Type)", sdk.typeof("via.Transform")) end)
	if not ok2 or comps == nil then return nil end
	local ok3, elements = pcall(function() return comps:get_elements() end)
	if not ok3 or elements == nil then return nil end
	for _, tr in ipairs(elements) do
		local okn, g, nm = pcall(function() local g = tr:call("get_GameObject"); return g, g and g:call("get_Name") end)
		if okn and nm == name then return g end
	end
	return nil
end

--(2) Find a descendant transform by its GameObject name
function sm32.transform_find(xform, name)
	if xform == nil then return nil end
	local ok, found = pcall(function() return xform:call("find(System.String)", name) end)
	if ok and found ~= nil then return found end
	sm32.note("Transform.find")
	local budget = 20000
	local function walk(node, depth)
		if node == nil or depth > 64 then return nil end
		local okc, child = pcall(function() return node:call("get_Child") end)
		local cur = okc and child or nil
		while cur ~= nil do
			budget = budget - 1
			if budget < 0 then return nil end
			local okn, nm = pcall(function() return cur:call("get_GameObject"):call("get_Name") end)
			if okn and nm == name then return cur end
			local hit = walk(cur, depth + 1)
			if hit ~= nil then return hit end
			local okx, nxt = pcall(function() return cur:call("get_Next") end)
			cur = okx and nxt or nil
		end
		return nil
	end
	return walk(xform, 0)
end

--(3a) Managed array creation (accepts a type name or a RETypeDefinition)
-- Some REFramework builds create arrays but cannot write elements:
-- prove one write before trusting a fresh array.
local function sm32_array_writable(arr, elem, count)
	if count == nil or count == 0 then return true end
	local sample = nil
	if type(elem) == "string" then pcall(function() local i = sdk.create_instance(elem) or sdk.create_instance(elem, true); sample = i and i:add_ref() end) end
	if sample == nil then return true end
	local ok = pcall(function() arr[0] = sample end)
	local rb = nil
	if ok then pcall(function() rb = arr[0] end) end
	if not (ok and rb ~= nil) then sm32.note("array element writes unsupported on this REFramework build") end
	return ok and rb ~= nil
end
function sm32.create_array(elem, count)
	if elem == nil then return nil end
	local ok, arr = pcall(function() local a = sdk.create_managed_array(elem, count); return a and a:add_ref() end)
	if ok and arr ~= nil and sm32_array_writable(arr, elem, count) then return arr end
	if type(elem) == "string" then
		local td = sdk.find_type_definition(elem)
		if td ~= nil then
			ok, arr = pcall(function() local a = sdk.create_managed_array(td, count); return a and a:add_ref() end)
			if ok and arr ~= nil then return arr end
		end
	end
	sm32.note("create_managed_array:"..tostring(elem))
	return nil
end

--(3b) System.Array.Clone still works; use a live array of the same field as a template
function sm32.clone_array(arr)
	if arr == nil then return nil end
	local ok, clone = pcall(function() return arr:call("Clone") end)
	if ok and clone ~= nil then return clone end
	sm32.note("Array.Clone")
	return nil
end

--(3c) Element write with a SetValue fallback
function sm32.array_set(arr, index, value)
	if arr == nil then return false end
	if pcall(function() arr[index] = value end) then return true end
	sm32.note("array element write")
	return (pcall(function() arr:call("SetValue(System.Object, System.Int32)", value, index) end))
end

--(4) via.Color assignment.
--
--    The engine's own constructors are asked first, and the packed 'rgba' field write is the
--    fallback for a build where they cannot be reached.  It used to be the other way round, and
--    that is why colours came out slightly wrong: the conversion from the picker's 0-to-1 channels
--    to bytes belongs to the engine, and every colour anyone has ever tuned in this mod was tuned
--    against the engine's version of it.  Doing it by hand here is a straight multiply by 255, and
--    it also flattens a channel set above 1.0 - which the pickers allow on purpose, for a glow.
--
--    The constructors do not report success, so the field is cleared first and read back: a call
--    that resolved but wrote nothing is then indistinguishable from a genuinely black transparent
--    colour, and both fall through to the hand-written pack, which produces the same value.
function sm32.color_vec4(colour, vec4)
	if colour == nil or vec4 == nil then return colour end
	local function b(v) v = math.floor((tonumber(v) or 0) * 255 + 0.5); if v < 0 then v = 0 elseif v > 255 then v = 255 end; return v end
	pcall(function() colour.rgba = 0 end)
	local landed = false
	if pcall(function() colour:call(".ctor(via.vec4)", vec4) end) then
		pcall(function() landed = (colour.rgba ~= 0) end)
	end
	if landed then return colour end
	sm32.note("via.Color .ctor(via.vec4)")
	pcall(function() colour.rgba = b(vec4.x) + b(vec4.y)*256 + b(vec4.z)*65536 + b(vec4.w)*16777216 end)
	return colour
end

function sm32.color_rgba(colour, r, g, b, a)
	if colour == nil then return colour end
	local function c(v) v = math.floor(tonumber(v) or 0); if v < 0 then v = 0 elseif v > 255 then v = 255 end; return v end
	pcall(function() colour.rgba = 0 end)
	local landed = false
	if pcall(function() colour:call(".ctor(System.Int32, System.Int32, System.Int32, System.Int32)", c(r), c(g), c(b), c(a)) end) then
		pcall(function() landed = (colour.rgba ~= 0) end)
	end
	if landed then return colour end
	sm32.note("via.Color .ctor(System.Int32 x4)")
	pcall(function() colour.rgba = c(r) + c(g)*256 + c(b)*65536 + c(a)*16777216 end)
	return colour
end

--Resolves a character's app.WorkRate. The .WorkRate property shorthand does not resolve
--on current REFramework builds; try the getter, then the component on the GameObject.
local sm32_workrate_cache = {}
function sm32.workrate(chara)
	if chara == nil then return nil end
	local okv, valid = pcall(function() return chara:get_Valid() end)
	if okv and valid == false then return nil end
	local addr = nil
	pcall(function() addr = chara:get_address() end)
	if addr and sm32_workrate_cache[addr] ~= nil then return sm32_workrate_cache[addr] or nil end
	local wr = nil
	pcall(function() wr = chara.WorkRate end)
	if wr == nil then pcall(function() wr = chara:call("get_WorkRate") end) end
	if wr == nil then pcall(function() wr = chara["<WorkRate>k__BackingField"] end) end
	if wr == nil then
		pcall(function()
			local go = chara:call("get_GameObject")
			if go then wr = func.getC(go, "app.WorkRate") end
		end)
	end
	if wr == nil then sm32.note("app.WorkRate lookup") end
	if addr then sm32_workrate_cache[addr] = wr or false end
	return wr
end

--Reads a via.Color's channels. The get_r()/get_g() method shorthand returns 0 on a
--ValueType under current REFramework builds, so the packed 'rgba' field is unpacked.
function sm32.color_get(colour)
	if colour == nil then return 0, 0, 0, 0 end
	local ok, packed = pcall(function() return colour.rgba end)
	if ok and type(packed) == "number" then
		return packed & 0xFF, (packed >> 8) & 0xFF, (packed >> 16) & 0xFF, (packed >> 24) & 0xFF
	end
	local ok2, r, g, b, a = pcall(function() return colour:call("get_r"), colour:call("get_g"), colour:call("get_b"), colour:call("get_a") end)
	if ok2 then return r or 0, g or 0, b or 0, a or 0 end
	return 0, 0, 0, 0
end

--(5) Guarded native-singleton call.  Returns nil instead of throwing.
--    No table allocation, so this stays safe on the per-frame paths.
--    The singleton and its type description are looked up once and kept: neither changes for the
--    life of the process, and this is called from the frame update and from an input hook that
--    runs for every character that carries input.
sm32.native_singletons = {}
sm32.native_types = {}

function sm32.native(singleton, typename, method, ...)
	local s = sm32.native_singletons[singleton]
	if s == nil then
		s = sdk.get_native_singleton(singleton)
		sm32.native_singletons[singleton] = s or false
	elseif s == false then
		s = nil
	end
	local td = sm32.native_types[typename]
	if td == nil then
		td = sdk.find_type_definition(typename)
		sm32.native_types[typename] = td or false
	elseif td == false then
		td = nil
	end
	if s == nil or td == nil then
		sm32.note("native singleton missing:"..tostring(singleton))
		return nil
	end
	local ok, ret = pcall(sdk.call_native_func, s, td, method, ...)
	if ok then return ret end
	sm32.note("call_native_func:"..typename.."."..method)
	return nil
end

--(6a) Overload resolution by name, for when the exact signature string no longer
--     matches.  app.GenerateManager's callback parameters carry generated generic
--     argument type names (app.DummyArg_2_0_0_13/14) and requestDestroy takes a
--     trailing run of booleans whose count varies by build, so the signature strings
--     this script hard-codes do not resolve.  Selecting the overload by its name and
--     its first parameter type survives that kind of churn.  Returns the method and
--     its parameter count.
--Answers are memoised: the scan walks every method the type has, which is several hundred on the
--larger managers, and some callers ask on a frame loop.  A miss is remembered too, so a type that
--simply has no such overload is not re-scanned and does not re-report.
sm32.overloads = {}

function sm32.overload(typename, basename, first_param)
	local key = typename.."."..basename.."("..tostring(first_param)..")"
	local memo = sm32.overloads[key]
	if memo ~= nil then
		if memo == false then return nil, 0 end
		return memo[1], memo[2]
	end
	local td = sdk.find_type_definition(typename)
	if td == nil then sm32.note("missing type:"..typename); sm32.overloads[key] = false; return nil, 0 end
	local best, best_n
	local ok, methods = pcall(function() return td:get_methods() end)
	for _, m in ipairs(ok and methods or {}) do
		if m:get_name() == basename then
			local okp, ps = pcall(function() return m:get_param_types() end)
			ps = (okp and ps) or {}
			local first_ok = (first_param == nil)
			if not first_ok and ps[1] ~= nil then
				local okn, n = pcall(function() return ps[1]:get_full_name() end)
				first_ok = okn and n == first_param
			end
			if first_ok and (best == nil or #ps < best_n) then best, best_n = m, #ps end
		end
	end
	if best == nil then
		sm32.overloads[key] = false
		sm32.note("missing overload:"..typename.."."..basename)
		log.error("[SkillMaker] engine compat: no overload of "..typename.."."..basename.." matched"..
			(first_param and (" (first parameter "..first_param..")") or ""))
		return nil, 0
	end
	sm32.overloads[key] = {best, best_n}
	return best, best_n
end

--(5a) The merged gamepad device is exposed as the parameterless property getter
--     via.hid.GamePad.get_MergedDevice() on this build; the older form was
--     getMergedDevice(int).  Calling only the older form returns nil, which makes the
--     mod treat every install as keyboard-only even with a pad plugged in.  Try the
--     property form first, then the older one.
--Cache only successful engine handles; physical connection is still checked on each call.
function sm32.pad_engine()
    if sm32.pad_singleton == nil then
        sm32.pad_singleton = sdk.get_native_singleton("via.hid.GamePad") or sdk.get_native_singleton("via.hid.Gamepad")
    end
    if sm32.pad_type == nil then
        sm32.pad_type = sdk.find_type_definition("via.hid.GamePad")
    end
    return sm32.pad_singleton, sm32.pad_type
end

function sm32.gamepad_device()
	local s, td = sm32.pad_engine()
	if s == nil or td == nil then
		sm32.note("via.hid.GamePad singleton missing")
		return nil
	end
	if td:get_method("get_MergedDevice") ~= nil then
		local ok, d = pcall(sdk.call_native_func, s, td, "get_MergedDevice")
		if ok and d ~= nil then return d end
	end
	local ok, d = pcall(sdk.call_native_func, s, td, "getMergedDevice", 0)
	if ok and d ~= nil then return d end
	sm32.note("gamepad merged device unavailable")
	return nil
end

--(6c) Is a gamepad physically connected?  get_MergedDevice() answers even with no pad
--     plugged in and via.hid.GamePadDevice has no get_Connecting() on this build, so the
--     only usable query is the parameterless via.hid.GamePad.getConnectingDevicesCount().
--     When it cannot be asked the caller supplies the 'unknown' answer, which is the one
--     that leaves the game's own bindings alone.
function sm32.pad_connected(unknown)
	local s, td = sm32.pad_engine()
	if s ~= nil and td ~= nil then
		if sm32.pad_count_method == nil then
			sm32.pad_count_method = td:get_method("getConnectingDevicesCount") or false
		end
	end
	if s ~= nil and td ~= nil and sm32.pad_count_method ~= false and sm32.pad_count_method ~= nil then
		local ok, count = pcall(sdk.call_native_func, s, td, "getConnectingDevicesCount")
		if ok and type(count) == "number" then return count > 0 end
	end
	sm32.note("GamePad.getConnectingDevicesCount")
	return unknown or false
end

--(6) Nil-checked managed method lookup
function sm32.method(typename, methodname)
	local td = sdk.find_type_definition(typename)
	local m = td and td:get_method(methodname)
	if m == nil then
		sm32.note("missing method:"..typename.."."..methodname)
		log.error("[SkillMaker] engine compat: method not found: "..typename.."."..methodname)
	end
	return m
end

--(6b) app.BodyEditor exposes the rebind step as either rebinding() or
--     preparationRebinding(), depending on the build.  Call whichever name this
--     build actually has, and degrade to a single logged note if neither is there.
function sm32.body_rebind(body_editor)
	if body_editor == nil then return end
	local ok, td = pcall(function() return body_editor:get_type_definition() end)
	if not ok or td == nil then return end
	for _, name in ipairs({"rebinding", "preparationRebinding"}) do
		if td:get_method(name) ~= nil then
			pcall(function() body_editor:call(name) end)
			return
		end
	end
	sm32.note("BodyEditor rebinding")
end

--Guarded managed instance creation (add_ref'd, like the original call sites)
function sm32.create_instance(typename)
	local ok, inst = pcall(function() local o = sdk.create_instance(typename); return o and o:add_ref() end)
	if ok and inst ~= nil then return inst end
	sm32.note("create_instance:"..typename)
	log.error("[SkillMaker] engine compat: could not create an instance of "..typename)
	return nil
end

--Guarded ValueType construction
function sm32.valuetype(typename)
	local ok, v = pcall(function() return ValueType.new(sdk.find_type_definition(typename)) end)
	if ok and v ~= nil then return v end
	sm32.note("ValueType.new:"..typename)
	log.error("[SkillMaker] engine compat: could not create a "..typename.." value")
	return nil
end

--Guarded hook registration.  A nil method used to crash the whole script at
--load; now only that hook is skipped, it is reported, and the rest register.
function sm32.hook(typename, methodname, pre_fn, post_fn, ignore_jmp)
	local td = sdk.find_type_definition(typename)
	local method = td and td:get_method(methodname)
	if method == nil then
		sm32.hooks_failed = sm32.hooks_failed + 1
		sm32.failed_hooks[#sm32.failed_hooks+1] = typename.."."..methodname.." (no such method)"
		log.error("[SkillMaker] engine compat: hook target not found: "..typename.."."..methodname)
		return false
	end
	local ok, err = pcall(sdk.hook, method, pre_fn, post_fn, ignore_jmp)
	if not ok then
		sm32.hooks_failed = sm32.hooks_failed + 1
		sm32.failed_hooks[#sm32.failed_hooks+1] = typename.."."..methodname.." ("..tostring(err)..")"
		log.error("[SkillMaker] engine compat: sdk.hook failed for "..typename.."."..methodname..": "..tostring(err))
		return false
	end
	sm32.hooks_ok = sm32.hooks_ok + 1
	return true
end

--(7) via.Scene.findFolder(System.String) is another string-argument native call
--    that throws on this build.  Fall back to walking the scene's folder list.
function sm32.find_folder(scene, name)
	if scene == nil then return nil end
	local ok, folder = pcall(function() return scene:call("findFolder(System.String)", name) end)
	if ok and folder ~= nil then return folder end
	sm32.note("Scene.findFolder")
	--get_FirstFolder only gives the four root folders, so recurse through get_Child/get_Next
	local budget = 8192
	local function walk(f)
		while f ~= nil and budget > 0 do
			budget = budget - 1
			local okn, nm = pcall(function() return f:call("get_Name") end)
			if okn and nm == name then return f end
			local okc, child = pcall(function() return f:call("get_Child") end)
			if okc and child ~= nil then
				local hit = walk(child)
				if hit ~= nil then return hit end
			end
			local okx, nxt = pcall(function() return f:call("get_Next") end)
			f = okx and nxt or nil
		end
		return nil
	end
	local ok2, first = pcall(function() return scene:call("get_FirstFolder") end)
	local hit = walk(ok2 and first or nil)
	if hit ~= nil then return hit end
	--last resort: the scene's own sibling chain
	local ok3, cur = pcall(function() return scene:call("get_FirstFolder") end)
	cur = ok3 and cur or nil
	while cur ~= nil and budget > 0 do
		budget = budget - 1
		local okn, nm = pcall(function() return cur:call("get_Name") end)
		if okn and nm == name then return cur end
		local okx, nxt = pcall(function() return scene:call("getNextFolder(via.Folder)", cur) end)
		cur = okx and nxt or nil
	end
	return nil
end

--(8) via.matrix.makeLookAtRH is not present in the TDB on this build, and no
--    other method on via.matrix builds a look-at.  Rebuild the same
--    right-handed view matrix in Lua - identical to glm::lookAtRH /
--    XMMatrixLookAtRH, which is what the engine method returned - and hand it
--    out behind a :call(nil, eye, at, up) shim so no call site changes.
function sm32.look_at_rh(eye, at, up)
	local z = (eye - at):normalized()
	up = up or Vector3f.new(0, 1, 0)
	local x = up:cross(z)
	if x:length() < 1e-6 then
		--up is parallel to the view direction: pick any perpendicular axis
		x = Vector3f.new(z.y, z.z, z.x):cross(z)
		if x:length() < 1e-6 then x = Vector3f.new(1, 0, 0) end
	end
	x = x:normalized()
	local y = z:cross(x)
	return Matrix4x4f.new(
		Vector4f.new(x.x, y.x, z.x, 0.0),
		Vector4f.new(x.y, y.y, z.y, 0.0),
		Vector4f.new(x.z, y.z, z.z, 0.0),
		Vector4f.new(-x:dot(eye), -y:dot(eye), -z:dot(eye), 1.0))
end

sm32.lookat_shim = { call = function(_, _, eye, at, up) return sm32.look_at_rh(eye, at, up) end }

function sm32.lookat_method()
	local td = sdk.find_type_definition("via.matrix")
	local m = td and td:get_method("makeLookAtRH")
	if m ~= nil then return m end
	sm32.note("via.matrix.makeLookAtRH removed (Lua look-at in use)")
	return sm32.lookat_shim
end

--(9) Entries in app.KeyBindController's keybind table and in
--    app.CharacterInput.PadAssign.AssignList are keyed by hashes that do not all
--    resolve on this build, so a lookup can come back nil.  Read one safely, and
--    say so in the log once.
function sm32.keybind_key(keybinds, hash)
	local ok, key = pcall(function()
		local kb = keybinds and keybinds[hash]
		return kb and kb._PrimaryKey
	end)
	if ok and key ~= nil then return key end
	sm32.note("keybind hash missing:"..tostring(hash))
	return nil
end

--(10) via.gui.Control.getObject(System.String) resolves but throws (the same
--     string-argument native call problem as findGameObject).  Walk the gui tree
--     by path segment instead, using get_Child / get_Next / get_Name.
function sm32.gui_get_object(get_method, root, path)
	if root == nil or path == nil then return nil end
	if get_method ~= nil then
		local ok, obj = pcall(function() return get_method:call(root, path) end)
		if ok and obj ~= nil then return obj end
	end
	sm32.note("via.gui.Control.getObject")
	local node = root
	for seg in tostring(path):gmatch("[^/]+") do
		local found, budget = nil, 4096
		local okc, child = pcall(function() return node:call("get_Child") end)
		local cur = okc and child or nil
		while cur ~= nil and budget > 0 do
			budget = budget - 1
			local okn, nm = pcall(function() return cur:call("get_Name") end)
			if okn and nm == seg then found = cur; break end
			local okx, nxt = pcall(function() return cur:call("get_Next") end)
			cur = okx and nxt or nil
		end
		if found == nil then return nil end
		node = found
	end
	return node
end

--(11) via.gui.Text.set_Message(System.String) is another string-argument native call
--     that throws on this build.  Try the property form, then the explicit signature, and
--     give up quietly rather than raising once per HUD button per frame.
function sm32.set_message(txt_obj, msg)
	if txt_obj == nil then return false end
	if pcall(function() txt_obj:set_Message(msg) end) then return true end
	if pcall(function() txt_obj:call("set_Message(System.String)", msg) end) then return true end
	sm32.note("via.gui.Text.set_Message (in-game button labels unavailable)")
	return false
end

--(12) Optional diagnostic channel.  Off by default; switched on from Mod Options.  Every line
--     goes to the REFramework log and the console, is tagged so it can be grepped out of a busy
--     log, and repeats of the same tag+text are collapsed to one line every few seconds so a
--     per-frame condition cannot flood the file.
sm32.dbg_seen = {}
sm32.dbg_on = false

function sm32.dbg(tag, msg)
	if not sm32.dbg_on then return end
	local key = tag..":"..tostring(msg)
	local now = os.clock()
	local last = sm32.dbg_seen[key]
	if last and now - last < 15.0 then return end
	sm32.dbg_seen[key] = now
	local line = "[SkillMaker][dbg]["..tag.."] "..tostring(msg)
	print(line); log.info(line)
end

--     A frame profiler on the same switch.  It accumulates the time each major section of the
--     frame update costs and prints one line every ten seconds, so a report can name the hot
--     section instead of describing it.  Nothing is measured and nothing is allocated while the
--     diagnostic channel is off.  os.clock() only ticks once per millisecond here, which is far
--     coarser than the sections being measured, so a high resolution engine counter is preferred
--     when this build has one.
sm32.prof = {}
sm32.prof_stack = {}
sm32.prof_frames = 0
sm32.prof_since = 0

do
	local app_s = sdk.get_native_singleton("via.Application")
	local app_td = sdk.find_type_definition("via.Application")
	local ok, ms = false, nil
	if app_s ~= nil and app_td ~= nil then
		ok, ms = pcall(sdk.call_native_func, app_s, app_td, "get_CurrentElapsedTimeMillisecond")
	end
	if ok and type(ms) == "number" then
		sm32.prof_clock_name = "via.Application elapsed milliseconds"
		sm32.prof_clock = function()
			local got, v = pcall(sdk.call_native_func, app_s, app_td, "get_CurrentElapsedTimeMillisecond")
			return (got and type(v) == "number") and v * 0.001 or os.clock()
		end
	else
		sm32.prof_clock_name = "os.clock, one millisecond resolution"
		sm32.prof_clock = os.clock
	end
end

function sm32.prof_begin()
	if not sm32.dbg_on then return end
	sm32.prof_stack[#sm32.prof_stack+1] = sm32.prof_clock()
end

function sm32.prof_end(name)
	if not sm32.dbg_on then return end
	local depth = #sm32.prof_stack
	if depth == 0 then return end
	local started = sm32.prof_stack[depth]
	sm32.prof_stack[depth] = nil
	sm32.prof[name] = (sm32.prof[name] or 0) + (sm32.prof_clock() - started)
end

--Called once at the end of the frame update.  Prints the breakdown every ten seconds and starts
--a fresh window; switching the channel off clears whatever had been collected.
function sm32.prof_frame()
	if not sm32.dbg_on then
		--a section that was opened on the frame the channel was switched off never closes, so the
		--whole of the collected state is dropped rather than carried into the next window
		if sm32.prof_frames ~= 0 or #sm32.prof_stack > 0 then
			sm32.prof, sm32.prof_stack, sm32.prof_frames, sm32.prof_since = {}, {}, 0, 0
		end
		return
	end
	local now = os.clock()
	if sm32.prof_since == 0 then sm32.prof_since = now; return end
	sm32.prof_frames = sm32.prof_frames + 1
	if now - sm32.prof_since < 10.0 then return end
	local frames = sm32.prof_frames > 0 and sm32.prof_frames or 1
	local names, total = {}, 0.0
	for name, secs in pairs(sm32.prof) do names[#names+1] = name; total = total + secs end
	table.sort(names, function(a, b) return sm32.prof[a] > sm32.prof[b] end)
	local parts = {}
	for i = 1, #names do
		parts[#parts+1] = string.format("%s %.3f", names[i], sm32.prof[names[i]] * 1000.0 / frames)
	end
	local line = string.format("[SkillMaker][dbg][perf] %d frames over %.1f s, %.3f ms per frame in the mod"
		.." (milliseconds per frame, %s): %s",
		frames, now - sm32.prof_since, total * 1000.0 / frames, sm32.prof_clock_name,
		#parts > 0 and table.concat(parts, ", ") or "nothing measured")
	print(line); log.info(line)
	sm32.prof, sm32.prof_stack, sm32.prof_frames, sm32.prof_since = {}, {}, 0, now
end

--(13) A keyboard key's release edge.  The shared hotkey library only refreshes its 'down' and
--     'triggered' keyboard tables on this game, so its released state stays false for every
--     keyboard key and any hotkey that is read in release mode never answers.  Gamepad and
--     mouse buttons are unaffected, so the library's own answer is kept and only the missing
--     keyboard edge is reconstructed here, from the 'down' state, once per frame.
sm32.hk_down_prev = {}
sm32.hk_up_edge = {}
sm32.up_actions = {"SM Clean Up", "Reset Player State", "Undo", "Redo", "Run Enemy Skill Test"}

function sm32.hk_scan(names)
	for i, name in ipairs(names) do
		local ok, down = pcall(sm32.hk.check_hotkey, name, true)
		down = ok and down and true or false
		sm32.hk_up_edge[name] = (sm32.hk_down_prev[name] == true) and not down
		sm32.hk_down_prev[name] = down
	end
end

--'released' answer for an action name: whichever of the library's own answer or the
--reconstructed keyboard edge is true this frame.
function sm32.hk_up(name)
	local ok, up = pcall(sm32.hk.check_hotkey, name)
	return (ok and up) or sm32.hk_up_edge[name] or false
end

--(14) Motion FSM node lookup.  tree:get_node_by_name() can come back nil on this build even for
--     a node the character really has, which silently disabled every Action node (the node object
--     is what the cast path used to decide whether to request the action at all).  Try the name
--     lookup first, then walk the tree's own node list and match by name, and report which route
--     answered.  Results are memoised per tree object so the walk happens at most once per name.
sm32.node_cache = setmetatable({}, {__mode = "k"})

--A character's behaviour tree for one motion layer, or nil.  Every step of the chain can be absent.
function sm32.fsm_tree(fsm, layer)
	if fsm == nil then return nil end
	local ok, tree = pcall(function()
		local l = fsm:getLayer(layer or 0)
		return l and l:get_tree_object() or nil
	end)
	return (ok and tree) or nil
end

--Which motion layer owns an action, asked of the behaviour tree itself rather than guessed from
--the shipped action list.  via.behaviortree.BehaviorTree.hasNode(name, treeIndex) answers per tree,
--and every motion layer is one tree, so this gives the real layer even when the node object cannot
--be reached.  Returns nil when the character has no such node on any layer.
function sm32.node_layer(fsm, name)
	if fsm == nil or type(name) ~= "string" or name == "" then return nil end
	local short = name:match(".+%.(.+)") or name
	local ok_count, count = pcall(function() return fsm:call("getTreeCount()") end)
	count = (ok_count and type(count) == "number" and count > 0) and count or 2
	for layer = 0, math.min(count, 8) - 1 do
		local ok, has = pcall(function() return fsm:call("hasNode(System.String, System.UInt32)", short, layer) end)
		if ok and has == true then return layer end
	end
	local ok1, has1 = pcall(function() return fsm:call("hasNode(System.String)", short) end)
	if ok1 and has1 == true then return 0 end
	if not ok1 then sm32.note("BehaviorTree.hasNode") end
	return nil
end

--Move a character's motion layer onto a named node.  The layer-level setCurrentNode is absent on
--this build; the component-level BehaviorTree.setCurrentNode(name, treeIndex, SetNodeInfo) is the
--one that resolves, and the interpolation the old call carried is set on the layer beforehand.
function sm32.fsm_set_node(fsm, layer, name, node_info, transition)
	if fsm == nil or type(name) ~= "string" or node_info == nil then return false end
	if transition ~= nil then
		pcall(function() fsm:getLayer(layer or 0):call("setNextMotionTransition(via.motion.SetMotionTransitionInfo)", transition) end)
	end
	local ok = pcall(function() fsm:call("setCurrentNode(System.String, System.UInt32, via.behaviortree.SetNodeInfo)", name, layer or 0, node_info) end)
	if not ok then sm32.note("BehaviorTree.setCurrentNode") end
	return ok
end

--One-shot report of which node-enumeration calls this build's behaviour-tree binding answers, so a
--single play session says whether the node object can be reached at all.
function sm32.tree_probe(tree, fsm)
	if sm32.tree_probed or not sm32.dbg_on then return end
	sm32.tree_probed = true
	local out = {}
	local function try(label, fn)
		local ok, v = pcall(fn)
		out[#out+1] = label.."="..(ok and tostring(v) or "raised")
	end
	try("get_node_count", function() return tree:get_node_count() end)
	try("get_nodes#", function() local n = tree:get_nodes(); return n and #n end)
	try("get_node(0)", function() return tree:get_node(0) end)
	try("get_node_by_name", function() return tree:get_node_by_name("NormalLocomotion") end)
	try("get_action_count", function() return tree:get_action_count() end)
	try("get_data", function() return tree:get_data() end)
	try("TotalNodeCount", function() return fsm:call("get_TotalNodeCount()") end)
	try("getTreeCount", function() return fsm:call("getTreeCount()") end)
	try("hasNode", function() return fsm:call("hasNode(System.String)", "NormalLocomotion") end)
	sm32.dbg("fsm", "behaviour tree capability: "..table.concat(out, ", "))
end

--A build where neither route exists at all answers nothing, ever, and each attempt costs a raised
--call.  The two capabilities are remembered the first time each is asked for, so a lookup on such a
--build settles into a single table read instead of two raises, however often it is asked.
sm32.tree_byname = nil --nil unknown, false the call itself is absent on this build
sm32.tree_walk = nil

function sm32.tree_node(tree, name)
	if tree == nil or type(name) ~= "string" or name == "" then return nil end
	if sm32.tree_byname == false and sm32.tree_walk == false then return nil end
	local short = name:match(".+%.(.+)") or name
	local cache = sm32.node_cache[tree]
	if cache == nil then cache = {}; sm32.node_cache[tree] = cache end
	local hit = cache[short]
	if hit ~= nil then return hit or nil end

	local ok, node
	if sm32.tree_byname ~= false then
		ok, node = pcall(function() return tree:get_node_by_name(short) end)
		if ok and node ~= nil then sm32.tree_byname = true; cache[short] = node; return node end
		if not ok then sm32.tree_byname = false end --the call is absent rather than the node
	end

	--the by-name lookup did not answer: walk the node list once and build the whole map
	if not cache.walked and sm32.tree_walk ~= false then
		cache.walked = true
		local walked_ok, count = pcall(function() return tree:get_node_count() end)
		if not walked_ok then sm32.tree_walk = false end
		if walked_ok and type(count) == "number" and count > 0 then
			sm32.tree_walk = true
			for idx = 0, count - 1 do
				local got, other = pcall(function() return tree:get_node(idx) end)
				local got_name, other_name = false, nil
				if got and other ~= nil then got_name, other_name = pcall(function() return other:get_name() end) end
				if got_name and type(other_name) == "string" and cache[other_name] == nil then
					cache[other_name] = other
				end
			end
			sm32.dbg("fsm", "walked "..count.." tree nodes to build a name map")
		else
			sm32.note("behaviortree node lookup (get_node_by_name and get_node_count both unavailable)")
		end
		hit = cache[short]
		if hit ~= nil then return hit end
	end

	cache[short] = false
	return nil
end

--(15) The character's pad-assign table.  It is reached as a property on the character's input
--     component; when that shorthand does not resolve, ask app.UserInputManager for the current
--     one instead.  Everything that reads or writes the in-game control map goes through here so
--     a single failure is reported once rather than aborting the frame that carries the crosshair
--     ray and the Custom Function globals.
--This is asked for on every frame, and on this build the first two routes do not resolve, so
--probing all three each time meant two member lookups that miss and raise before the one that
--answers was even tried.  The route that worked is remembered and used directly from then on; it
--is only re-probed when it stops answering, and that re-probe is rate limited so a loading screen
--cannot put the full probe back on the frame loop.
sm32.pad_route = nil

local function sm32_pad_by_route(chara, route)
	if route == 3 then
		local mgr = sm32.input_mgr
		if mgr == nil then
			mgr = sdk.get_managed_singleton("app.UserInputManager")
			sm32.input_mgr = mgr
		end
		if mgr == nil then return nil end
		local got, pa = pcall(function() return mgr:call("getCurrentCharacterPadAssign()") end)
		return (got and pa) or nil
	end
	local ok, input = pcall(function() return chara:get_Input() end)
	if not ok or input == nil then return nil end
	local got, pa
	if route == 1 then
		got, pa = pcall(function() return input.PadAssign end)
	else
		got, pa = pcall(function() return input:get_PadAssign() end)
	end
	return (got and pa) or nil
end

function sm32.pad_assign(chara)
	if chara == nil then return nil end
	if sm32.pad_route ~= nil then
		local pa = sm32_pad_by_route(chara, sm32.pad_route)
		if pa ~= nil then return pa end
		sm32.pad_route = nil --the route that used to answer no longer does: probe again, below
	end
	local now = os.clock()
	if sm32.pad_probed_at and now - sm32.pad_probed_at < 0.5 then return nil end
	sm32.pad_probed_at = now
	for route = 1, 3 do
		local pa = sm32_pad_by_route(chara, route)
		if pa ~= nil then
			sm32.pad_route = route
			if route == 2 then sm32.note("CharacterInput.PadAssign via getter")
			elseif route == 3 then sm32.note("pad assign from UserInputManager") end
			return pa
		end
	end
	sm32.note("CharacterInput.PadAssign unavailable (in-game button remaps are skipped)")
	sm32.dbg("padassign", "no pad assign object could be resolved for the player this frame")
	return nil
end

--(16) Custom Function environment.  A user function is compiled with _ENV = _G and its variables
--     are merged into _G for the duration of the call, then removed again.  Two of the names it is
--     handed - the crosshair, and the per-frame ones below - are owned by the frame update rather
--     than by the function, so removing them there left the next reader with nil.  These names are
--     refreshed into the environment table before every call and are never deleted afterwards.
--Ways to obtain a via.Prefab for a resource path, in the order they are tried.  Each entry is the
--resource type and the holder type to wrap it in, or nil to use the resource object itself.
sm32.prefab_routes = {
	{"via.PrefabResource", "via.Prefab"},
	{"via.Prefab", "via.Prefab"},
}

--Collision layer the crosshair casts against. Terrain and walls answer on this one; the frame
--update sweeps for a replacement and adopts it if this ever stops returning contact points.
--The names below fill the Mod Options selector, and are kept in step with sm32.ray_layers.
sm32.ray_layer = 0
sm32.ray_layer_names = {"Auto", "Layer 0", "Layer 21", "Layer 25", "Layer 31"}

sm32.frame_globals = {Player=true, GameTime=true, Crosshair=true, ActiveSkills=true, ActiveSummons=true, Callbacks=true}

function sm32.fn_env_clear(fn_env)
	for key, value in pairs(fn_env or {}) do
		if not sm32.frame_globals[key] then _G[key] = nil end
	end
end

--(17) Point a via.Prefab at a resource path.  via.Prefab exposes get_Path() but no path setter in
--     this build's type database, and neither does app.PrefabController, so the single unguarded
--     call the summon routine used to make raised and took the whole routine with it before its
--     per-frame manager was ever installed - which is what stops summons appearing while every
--     other part of a skill still runs.  Try each route this build might have, report which one
--     answered, and let the caller carry on when none of them do.
--Does this object actually carry a prefab?  via.Prefab's own 'Path' member is the resource rather
--than a string, so the test is get_Exist(), which only a real via.Prefab answers with a boolean:
--a holder of the wrong type returns nil there and must not be accepted, or the summon routine
--carries an object that can never become ready.
function sm32.prefab_loaded(candidate)
	if candidate == nil then return false end
	local ok, exists = pcall(function() return candidate:call("get_Exist()") end)
	if not ok or type(exists) ~= "boolean" then return false end
	if exists then return true end
	--not resolved yet: a resource path read back still proves the holder is pointed somewhere
	local got, res_path = pcall(function() return candidate:call("get_ResourcePath()") end)
	return got and type(res_path) == "string" and res_path ~= ""
end

function sm32.prefab_path(pfb, path)
	if type(path) ~= "string" or path == "" then return nil end

	--A prefab resource wrapped in the holder the engine hands out for it.  This is the shape every
	--other resource in the script is built with, and it is what survives the loss of the path setter:
	--the path belongs to the resource, and via.Prefab is the holder around it.
	local function from_resource(res_type, holder_type)
		local ok, res = pcall(sdk.create_resource, res_type, path)
		if not ok or res == nil then return nil end
		local held
		ok, held = pcall(function()
			local r = res:add_ref()
			if holder_type == nil then return r end
			return r:create_holder(holder_type):add_ref()
		end)
		if ok and sm32.prefab_loaded(held) then return held end
		--the holder can also be built by hand: a resource holder keeps its resource pointer at 0x10
		if holder_type ~= nil then
			ok, held = pcall(function()
				local addr = res:add_ref():get_address()
				local h = sdk.create_instance(holder_type, true):add_ref()
				pcall(function() h:call(".ctor()") end)
				h:write_qword(0x10, addr)
				return h
			end)
			if ok and sm32.prefab_loaded(held) then
				sm32.note("prefab holder written by hand")
				return held
			end
		end
		return nil
	end

	--the path setter, for engine builds that still have it
	if pfb ~= nil then
		if pcall(function() pfb:set_Path(path) end) and sm32.prefab_loaded(pfb) then return pfb end
		if pcall(function() pfb:call("set_Path(System.String)", path) end) and sm32.prefab_loaded(pfb) then
			sm32.note("via.Prefab.set_Path by explicit signature")
			return pfb
		end
	end

	for i, route in ipairs(sm32.prefab_routes) do
		local built = from_resource(route[1], route[2])
		if built ~= nil then
			if sm32.prefab_route ~= i then
				sm32.prefab_route = i
				sm32.note("via.Prefab from "..route[1]..(route[2] and (" held as "..route[2]) or ""))
			end
			return built
		end
	end

	sm32.note("via.Prefab could not be built from a path (summons cannot be spawned)")
	sm32.dbg("summon", "no route produced a via.Prefab for '"..path.."'")
	return nil
end

--A prefab controller the game already owns for a character.  via.Prefab cannot be pointed at a
--path on this build - it holds a resource rather than a path string, and the holder type the
--resource system hands back is not a via.Prefab - so the working route is to let the character
--manager supply the controller for a character id instead of assembling one.
--A controller is only usable when it actually names a prefab; an empty one answers every call
--without ever becoming ready, which is the trap the resource-holder route fell into.
function sm32.ctrl_path(ctrl)
	if ctrl == nil then return nil end
	local ok, res_path = pcall(function() return ctrl:call("get_ResourcePath()") end)
	if ok and type(res_path) == "string" and res_path:find("%.pfb") then return res_path end
	return nil
end

function sm32.chara_prefab_ctrl(chara_id)
	if chara_id == nil then return nil end
	local mgr = sdk.get_managed_singleton("app.CharacterManager")
	if mgr == nil then return nil end
	local sig = "tryGetPrefabController(app.CharacterID, app.PrefabController)"

	--the second parameter is an out parameter, and how it is delivered depends on the binding:
	--either the object handed in is filled, or the call answers with the controller itself
	local ok, ctrl = pcall(function()
		local out = sdk.create_instance("app.PrefabController"):add_ref()
		local got = mgr:call(sig, chara_id, out)
		if type(got) == "userdata" and sm32.ctrl_path(got) then return got end
		if sm32.ctrl_path(out) then return out end
		return nil
	end)
	if ok and ctrl ~= nil then return ctrl end

	ok, ctrl = pcall(function()
		local got = mgr:call(sig, chara_id, nil)
		return (type(got) == "userdata" and sm32.ctrl_path(got)) and got or nil
	end)
	if ok and ctrl ~= nil then return ctrl end

	sm32.note("CharacterManager.tryGetPrefabController")
	sm32.dbg("summon", "the character manager did not supply a prefab controller for character id "..tostring(chara_id))
	return nil
end

--Spawning a character the game is not already spawning.
--
--app.GenerateManager offers two shapes of create request.  One takes an app.PrefabController and
--leaves the caller to supply the prefab; the others take only the generate info container and let
--the manager resolve and load the prefab from the character id the container already carries.
--via.Prefab has no path setter on this build, and the holder the resource system hands back for a
--.pfb is not a via.Prefab, so a controller cannot be assembled here at all - which is why the
--container-taking shapes are tried first and the controller shape is kept only as a last resort.
--Which shape a build answers is discovered at runtime: each is asked in turn, and the one that is
--in use when a character actually appears is kept and reported.
sm32.summon_routes = {
	{name = "safeRequestCreateInstance",  first = "app.GenerateInfo.GenerateInfoContainer"},
	{name = "forceRequestCreateInstance", first = "app.GenerateInfo.GenerateInfoContainer"},
	{name = "requestGenerate",            first = "app.GenerateInfo.GenerateInfoContainer"},
	{name = "requestCreateInstance",      first = "app.PrefabController", needs_ctrl = true},
}
sm32.summon_route_idx = 1

--Ask the manager to start loading the prefab a container names.  This is the engine-side
--counterpart of via.Prefab.set_Standby, which cannot be reached without a via.Prefab.
function sm32.summon_standby(gen_mgr, g_info)
	if gen_mgr == nil or g_info == nil then return false end
	local mth = sm32.overload("app.GenerateManager", "requestStandbyPrefab", "app.GenerateInfo.GenerateInfoContainer")
	if mth == nil then return false end
	local ok, err = pcall(function() mth:call(gen_mgr, g_info) end)
	if not ok and sm32.dbg_on then sm32.dbg("summon", "requestStandbyPrefab raised: "..tostring(err)) end
	return ok
end

--A character appeared, so whichever way it was last asked for is the one this build answers.
function sm32.summon_worked()
	if sm32.summon_confirmed then return end
	sm32.summon_confirmed = true
	local route = sm32.summon_routes[sm32.summon_route_idx]
	log.info("[SkillMaker] summons: characters are created through app.GenerateManager."
		..(route and route.name or "an unknown request").." on this build")
end

--Nothing appeared after several attempts, so step to the next way of asking.
function sm32.summon_failed()
	if sm32.summon_confirmed or sm32.summon_route_idx >= #sm32.summon_routes then return end
	sm32.summon_route_idx = sm32.summon_route_idx + 1
	local route = sm32.summon_routes[sm32.summon_route_idx]
	local msg = "[SkillMaker] summons: no character appeared; asking app.GenerateManager."
		..route.name.." instead"
	print(msg); log.info(msg)
end

--The character a create request produced, claimed from the manager's own list.
--
--Only the controller-taking request fills in the app.InstanceInfo it is handed.  The container-taking
--ones do not, so nothing on this side ever saw what they created: the character appeared in the
--world, the mod went on asking for it, stepped to the next way of asking, and never registered the
--one it had - which is why a summon could not be commanded, coloured or sent away again, and why the
--second one was asked for a different way than the first.
--
--The manager keeps a list of what it is instantiating and every entry names the container it came
--from, so the character is claimed from there instead.
function sm32.summon_instance(gen_mgr, g_info)
	if gen_mgr == nil or g_info == nil then return nil, nil end
	local obj, chara
	pcall(function()
		local target = g_info:get_address()
		local list = gen_mgr.InstantiateInstanceInfoList
		local items = list and list._items
		local count = (list and list._size) or 0
		for n = 0, count - 1 do
			local info = items and items[n]
			local container = info and info["<Container>k__BackingField"]
			if container ~= nil and container:get_address() == target then
				obj = info["<Instance>k__BackingField"]
				chara = info["<Chara>k__BackingField"]
				break
			end
		end
	end)
	return obj, chara
end

--Issue a create request for a container.  'pfb_ctrl' may be nil; the controller-taking shape is
--skipped when there is nothing to hand it.
function sm32.summon_request(gen_mgr, g_info, pfb_ctrl, i_info)
	if gen_mgr == nil or g_info == nil then return false end
	for idx = sm32.summon_route_idx, #sm32.summon_routes do
		local route = sm32.summon_routes[idx]
		if not (route.needs_ctrl and pfb_ctrl == nil) then
			local mth, count = sm32.overload("app.GenerateManager", route.name, route.first)
			if mth ~= nil then
				--the trailing parameters are callbacks and option flags on every shape, and their
				--number varies by build, so they are padded out to whatever arity the overload wants
				local args = route.needs_ctrl and {pfb_ctrl, g_info, 0, i_info} or {g_info}
				for k = #args + 1, count do args[k] = 0 end
				local ok, err = pcall(function() mth:call(gen_mgr, table.unpack(args, 1, count)) end)
				if ok then
					sm32.summon_route_idx = idx
					if sm32.summon_asked ~= route.name then
						sm32.summon_asked = route.name
						log.info("[SkillMaker] summons: asking app.GenerateManager."..route.name
							.." ("..tostring(count).." parameters) for the character")
					end
					return true
				end
				if sm32.dbg_on then
					sm32.dbg("summon", route.name.." ("..tostring(count).." parameters) raised: "..tostring(err))
				end
			end
		end
	end
	sm32.note("GenerateManager create request (no shape answered)")
	sm32.dbg("summon", "no create request on app.GenerateManager accepted the generate info container")
	return false
end

--One-shot report of where the summon path can get a prefab from on this game build.  via.Prefab
--cannot be pointed at a path here: it holds a resource rather than a path string, and the holder
--the resource system hands back for a .pfb is not a via.Prefab, so the character manager's own
--controller is the route that works.  One line per session, so a log always says which it used.
--One line per session naming every way this build can be asked to create a character, so a log
--always says what was available before the first summon was attempted.  Nothing is called here -
--the shapes are only looked up - so this is safe to run at the title screen.
function sm32.prefab_report()
	if sm32.prefab_reported then return end
	sm32.prefab_reported = true
	local found = {}
	for i, route in ipairs(sm32.summon_routes) do
		local mth, count = sm32.overload("app.GenerateManager", route.name, route.first)
		if mth ~= nil then found[#found+1] = route.name.."/"..tostring(count) end
	end
	local standby = sm32.overload("app.GenerateManager", "requestStandbyPrefab", "app.GenerateInfo.GenerateInfoContainer")
	log.info("[SkillMaker] summons: create requests available on app.GenerateManager: "
		..(#found > 0 and table.concat(found, ", ") or "none - character summons cannot spawn")
		..(standby and "; prefab standby available" or "; no prefab standby"))
end

--One-line load summary so in-game issues can be diagnosed from the log later
function sm32.summary(version)
	log.info("[SkillMaker] engine compat: v"..tostring(version)..
		" loaded; hooks "..sm32.hooks_ok.." ok / "..sm32.hooks_failed.." failed"..
		(sm32.hooks_failed > 0 and " ["..table.concat(sm32.failed_hooks, "; ").."]" or "")..
		"; fallbacks active at load: "..(#sm32.notes > 0 and table.concat(sm32.notes, ", ") or "none"))
	sm32.reported = true
end

