--SkillMaker.json is the only copy of the whole configuration, so it is read defensively and a standby
--copy is kept beside it. 'ok' records whether the file on disk was readable: if it was not, nothing in
--this session may overwrite it. State lives on sm32 because the main chunk is near Lua's 200-local limit.
sm32.cfg = {
	path = "SkillMaker\\SkillMaker.json",
	bak = "SkillMaker\\SkillMaker.bak.json",
	ok = true,
	owed = false,
	saved_at = 0.0,
	backed_at = -100.0,
}

function sm32.cfg.load(path)
	local worked, tbl = pcall(json.load_file, path)
	return worked and type(tbl) == "table" and next(tbl) ~= nil and tbl or nil
end

function sm32.cfg.exists(path)
	local worked, paths = pcall(fs.glob, "SkillMaker\\\\.*json")
	for i, found in ipairs(worked and paths or {}) do
		if found:lower():gsub("/", "\\") == path:lower() then return true end
	end
end

-- GSMAX external settings: SkillMaker.json is intentionally NOT embedded.
-- Keep reframework/data/SkillMaker/SkillMaker.json beside the standalone runtime.

local sms = sm32.cfg.load(sm32.cfg.path)
if not sms then
	sms = sm32.cfg.load(sm32.cfg.bak)
	if sms then
		re.msg("Skill Maker could not read reframework\\data\\SkillMaker\\SkillMaker.json"
		.."\nYour settings have been restored from SkillMaker.bak.json")
	else
		-- Never regenerate or overwrite a missing/unreadable external configuration.
		-- Use runtime defaults only for this session, not as a replacement file.
		sm32.cfg.ok = false
		sms = {}
		re.msg("GSMAX SkillMaker requires an external settings file:"
			.."\nreframework\\data\\SkillMaker\\SkillMaker.json"
			.."\nNo readable SkillMaker.bak.json was found either."
			.."\nRuntime defaults will be used for this session only;"
			.."\nexisting settings will NOT be overwritten.")
	end
end

--'was_changed' is raised by every imgui widget, and a drag or slider raises it on every frame the mouse
--moves, so the settings dump used to rewrite the whole multi-megabyte tree from the frame loop dozens of
--times a second, non-atomically and without ever looking at the result. Defer it to the frame the mouse
--comes up, rate limit it, refresh the standby copy on a frame of its own so the two files are never
--written together, and only clear the pending flag on a write that actually succeeded.
function sm32.save_settings(force)
	if not sm32.cfg.owed or not sm32.cfg.ok then return end
	local now = os.clock()
	if not force and now - sm32.cfg.owed < 5.0 then
		local worked, is_down = pcall(imgui.is_mouse_down)
		if worked and is_down then return end --a slider is being dragged: the write can wait for the release
		if now - sm32.cfg.saved_at < 0.5 then return end
	end
	sm32.cfg.saved_at = now
	if now - sm32.cfg.backed_at > 60.0 then
		sm32.cfg.backed_at = now
		json.dump_file(sm32.cfg.bak, sms)
		return
	end
	if json.dump_file(sm32.cfg.path, sms) == false then
		if not sm32.cfg.warned then
			sm32.cfg.warned = true
			log.error("Skill Maker could not write "..sm32.cfg.path)
		end
		return
	end
	sm32.cfg.owed, sm32.cfg.warned = false, nil
end

