--A settings file written before this option became device-specific carries it switched on for
--everybody.  Turn it off once for keyboard and mouse, and record that it has been done so a player
--who switches it back on keeps it.  Nothing else in the settings file is touched.
if (sms.settings_rev or 0) < 1 then
	sms.settings_rev = 1
	if not sms.use_gamepad_defaults then sms.modifier_inhibits_buttons = false end
end
do --a settings tree this build cannot use must not be silently replaced by defaults and written back
	local lists_ok, lists_err = pcall(setup_default_lists)
	if not lists_ok then
		local backup = sm32.cfg.load(sm32.cfg.bak) --try the standby copy before throwing the configuration away
		if backup then sms = func.convert_tbl_to_numeric_keys(hk.recurse_def_settings(backup, default_sms)) end
		if not (backup and pcall(setup_default_lists)) then
			sms = hk.recurse_def_settings({}, default_sms)
			setup_default_lists()

if GSMAX_HEADLESS_RUNTIME then sms.use_window = false end
			sm32.cfg.ok = false --defaults must never be written over settings that could not be read
		end
		re.msg("Skill Maker could not use your settings:\n"..tostring(lists_err).."\n\n"..(sm32.cfg.ok
			and "They have been restored from SkillMaker.bak.json"
			or "Skill Maker is running on default settings and will NOT overwrite"
			.."\nreframework\\data\\SkillMaker\\SkillMaker.json"))
	end
end
