	end,
}

--Returns a reason string when a blacklisted shell must not be cast, or nil when it is safe to cast.
--The blacklist was advisory only: it printed a warning in the editor and nothing checked it on the cast
--path, so these shells took the game down instantly. Job-specific shell files (..._jobNN.user) only
--crash when that vocation's weapon is not held (job09 / Trickster needs a Censer), so they stay usable
--for the vocation that owns them; blacklisted shells with no job in their file name are always refused.
function sm32.bad_shell_reason(udata_name, shell_id, owner)
	shell_id = tonumber(shell_id)
	if type(udata_name) ~= "string" or shell_id == nil then return nil end
	local short_name = udata_name:match(".+%/(.+)") or udata_name
	local listed = bad_shells[udata_name] or bad_shells[short_name]
	if not (listed and listed[shell_id]) then return nil end
	local req_wp = weps.job_to_wp_map[tonumber(udata_name:match("_job(%d%d)") or "") or -1]
	if not req_wp then return short_name.." shell "..shell_id.." is a known crash" end
	local got_wp, held_wp = pcall(function() return weps.getWeaponJob(owner:get_WeaponAndItemHolder():get_RightWeapon(), weps.job_to_wp_map) end)
	if got_wp and held_wp == req_wp then return nil end
	return short_name.." shell "..shell_id.." needs a "..req_wp.." equipped"
end

