local function update_last_sel_spells()
	for i, skill_tbl in ipairs(sms.skills) do
		imgui_skills[i].preset_text = skill_tbl.name
		sms.last_sel_spells[i] = skill_tbl.name
		imgui_skills[i].preset_idx = func.find_index(presets_glob, skill_tbl.name) or 1
	end
	for name, enemy_tbl in pairs(sms.enemyskills) do
		for i, skill_tbl in ipairs(enemy_tbl.skills) do
			local imgui_skill_list = imgui_em_skills[name]
			if imgui_skill_list then
				imgui_skill_list[i].preset_text = skill_tbl.name
				sms.last_sel_em_spells[name][i] = skill_tbl.name
				imgui_skill_list[i].preset_idx = func.find_index(imgui_skill_list[i].do_browse_pl_skills and presets_glob or em_presets_glob[name], skill_tbl.name) or 1
			end
		end
	end
end

--Reading reframework\data must never abort the main chunk: this is called at load time, before
--re.on_draw_ui is registered, so a throw here removes Skill Maker from the UI entirely and takes
--every dependent skill pack with it. A failed fs.glob becomes an empty list, and any file that no
--known enemy folder claims (a Fluffy misroute, a leftover from an older install, a skill whose name
--held a '/' so the exporter made a sub-folder) is collected and reported once instead of being
--handed to table.insert as a nil table. Hung off sm32 rather than a new local: the main chunk is
--near Lua's 200-local ceiling.
sm32.glob = {skipped={}, seen={}}

function sm32.glob.get(filter)
	local got_glob, glob = pcall(fs.glob, filter)
	if not got_glob or type(glob) ~= "table" then
		local msg = "[SkillMaker] Could not read reframework\\data for '"..tostring(filter).."': "..tostring(glob)
		print(msg); log.info(msg)
		return {}
	end
	return glob
end

function sm32.glob.skip(path)
	if not sm32.glob.seen[path] then
		sm32.glob.seen[path] = true
		sm32.glob.skipped[#sm32.glob.skipped+1] = path
	end
end

function sm32.glob.report()
	if #sm32.glob.skipped > 0 then
		local msg = "[SkillMaker] Ignored "..#sm32.glob.skipped.." file(s) that are not inside a known enemy folder: "..table.concat(sm32.glob.skipped, ", ")
		print(msg); log.info(msg)
		sm32.glob.skipped = {} --'seen' is kept, so a stray file is not reported again on a later rescan
	end
end

local function setup_skillsets_glob()
	local glob = sm32.glob.get("SkillMaker\\\\.*Skillsets\\\\.*json")
	enemy_skillsets, skillsets_glob = {"[Select Skillset]"}, {"[Select Skillset]", short={"[Select Skillset]"}}
	local combined_list = hk.merge_tables({["All Enemies"]={}}, enemy_action_names)
	
	for name, list in pairs(combined_list) do 
		enemy_skillsets[name] = enemy_skillsets[name] or {names={(name=="All Enemies") and "[Select Enemy Skillset List]" or "[Select Enemy Skillset]", "[Clear All]"}}
	end
	
	for i, path in ipairs(glob) do
		local path_name = path:match("Skillsets\\(.-)\\")
		if path:find("EnemySkillset") then
			if path_name and enemy_skillsets[path_name] then --any other folder name is not a known enemy and would index nil here
				table.insert(enemy_skillsets[path_name], path)
				table.insert(enemy_skillsets[path_name].names, path:match(".+\\(.+)%.json"))
			else
				sm32.glob.skip(path)
			end
		else
			table.insert(skillsets_glob, path)
			table.insert(skillsets_glob.short, path:match(".+\\(.+)%.json"))
		end
	end
end
if not pcall(setup_skillsets_glob) then
	print("[SkillMaker] Failed to build the skillset lists, they are empty this session")
	enemy_skillsets = enemy_skillsets or {"[Select Skillset]"}
	skillsets_glob = skillsets_glob or {"[Select Skillset]", short={"[Select Skillset]"}}
	enemy_skillsets["All Enemies"] = enemy_skillsets["All Enemies"] or {names={"[Select Enemy Skillset List]", "[Clear All]"}}
	for name, imgui_list in pairs(imgui_em_skills) do --the key set the enemy Skillset UI actually indexes
		enemy_skillsets[name] = enemy_skillsets[name] or {names={"[Select Enemy Skillset]", "[Clear All]"}}
	end
end

local function setup_presets_glob(do_descs)
	do_descs = do_descs or (presets_glob == false)
	presets_map = {}
	presets_glob, em_presets_glob = {"[Reset Skill Slot]", full_paths={""}}, {}
	local glob = sm32.glob.get("SkillMaker\\\\.*json")
	
	for i, path in ipairs(glob) do 
		local name = path:match("SkillMaker\\Skills\\(.+).json") 
		if name then
			table.insert(presets_glob, name)
			table.insert(presets_glob.full_paths, path)
			presets_map[name] = #presets_glob
		end
	end
	
	if do_descs or #sms.skill_descs ~= #presets_glob then 
		sms.skill_descs = {}
		for i=2, #presets_glob do 
			local json_data = json.load_file("SkillMaker\\Skills\\"..presets_glob[i]..".json")
			sms.skill_descs[i] = json_data and json_data.desc or "ERROR: Failed to read json file"
		end
	end
	
	for i, imgui_skill in ipairs(imgui_skills) do
		imgui_skill.preset_text = sms.last_sel_spells[i] or imgui_skill.preset_text
	end
	
	for name, imgui_list in pairs(imgui_em_skills) do
		em_presets_glob[name] = {"[Reset Skill Slot]", full_paths={""}}
		for i, imgui_skill in ipairs(imgui_list) do
			imgui_skill.preset_text = sms.last_sel_em_spells[name][i] or imgui_skill.preset_text
		end
	end
	
	for i, path in ipairs(glob) do 
		local em_name, filename = path:match("SkillMaker\\EnemySkills\\(.-)[\\/](.+).json")
		if em_name and filename then
			if em_presets_glob[em_name] then --em_presets_glob only holds keys of imgui_em_skills; any other folder would index nil here
				table.insert(em_presets_glob[em_name], filename)
				table.insert(em_presets_glob[em_name].full_paths, path)
			else
				sm32.glob.skip(path)
			end
		end
	end
	
	update_last_sel_spells()
	was_changed = true
end
if not pcall(setup_presets_glob) then --degrade to empty preset lists rather than killing the script
	print("[SkillMaker] Failed to build the skill preset lists, they are empty this session")
	presets_map = presets_map or {}
	presets_glob = presets_glob or {"[Reset Skill Slot]", full_paths={""}}
	em_presets_glob = em_presets_glob or {}
	for name, imgui_list in pairs(imgui_em_skills) do
		em_presets_glob[name] = em_presets_glob[name] or {"[Reset Skill Slot]", full_paths={""}}
	end
end
sm32.glob.report()

