						if sm32.dbg_on then sm32.dbg("summon", "get_Ready raised on the prefab source: "..tostring(rdy)) end
						return false
					end
					if not rdy and tics % 120 == 0 and sm32.dbg_on then
						sm32.dbg("summon", "prefab '"..tostring(pfb_path).."' has still not loaded")
					end
					return rdy
				end
				return true
			end)() then --spawn
